#!/usr/bin/env python3
import json
import re
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[3]
contract = json.loads((root / "packages/openapi/openapi.yaml").read_text())
paths = sorted(contract["paths"].keys())
operations = []
for path, item in contract["paths"].items():
    for method in ("get", "post", "put", "patch", "delete"):
        if method in item:
            operations.append((item[method]["operationId"], path, re.findall(r"\{([^}]+)\}", path)))
operations.sort()

ts_lines = [
    "// Generated by packages/openapi/scripts/generate-contracts.py; do not edit.\n",
    "export const openApiPaths = [\n",
]
for path in paths:
    ts_lines.append(f"  {json.dumps(path)},\n")
ts_lines.append("] as const;\n")
ts_lines.append("export type OpenApiPath = (typeof openApiPaths)[number];\n")
ts_lines.append("export const openApiOperations = {\n")
for operation_id, path, parameters in operations:
    if not parameters:
        ts_lines.append(f"  {operation_id}: {json.dumps(path)},\n")
        continue
    signature = ", ".join(f"{parameter}: string" for parameter in parameters)
    pieces = []
    position = 0
    for match in re.finditer(r"\{([^}]+)\}", path):
        if match.start() > position:
            pieces.append(json.dumps(path[position:match.start()]))
        pieces.append(f"encodeURIComponent({match.group(1)})")
        position = match.end()
    if position < len(path):
        pieces.append(json.dumps(path[position:]))
    ts_lines.append(f"  {operation_id}: ({signature}) => {' + '.join(pieces)},\n")
ts_lines.append("} as const;\n")
ts_content = "".join(ts_lines)

swift_lines = [
    "// Generated by packages/openapi/scripts/generate-contracts.py; do not edit.\n",
    "import Foundation\n\n",
    "public enum OpenAPIPaths {\n",
    "    private static let pathSegmentAllowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: \"-._~\"))\n",
    "    private static func segment(_ value: String) -> String {\n",
    "        value.addingPercentEncoding(withAllowedCharacters: pathSegmentAllowed) ?? \"\"\n",
    "    }\n\n",
    "    public static let all: [String] = [\n",
]
for path in paths:
    swift_lines.append(f"        {json.dumps(path)},\n")
swift_lines.append("    ]\n\n")
for operation_id, path, parameters in operations:
    if not parameters:
        swift_lines.append(f"    public static let {operation_id} = {json.dumps(path)}\n")
        continue
    signature = ", ".join(f"{parameter}: String" for parameter in parameters)
    pieces = []
    position = 0
    for match in re.finditer(r"\{([^}]+)\}", path):
        if match.start() > position:
            pieces.append(json.dumps(path[position:match.start()]))
        pieces.append(f"segment({match.group(1)})")
        position = match.end()
    if position < len(path):
        pieces.append(json.dumps(path[position:]))
    swift_lines.append(f"    public static func {operation_id}({signature}) -> String {{ {' + '.join(pieces)} }}\n")
swift_lines.append("}\n")
swift_content = "".join(swift_lines)

outputs = {
    root / "packages/shared-contracts/src/openapi-paths.ts": ts_content,
    root / "apps/admin-web/src/generated/openapi-paths.ts": ts_content,
    root / "apps/ios/Sources/EchoTrailsShell/Generated/OpenAPIPaths.swift": swift_content,
}

if "--check" in sys.argv[1:]:
    stale = [str(path.relative_to(root)) for path, expected in outputs.items() if not path.exists() or path.read_text() != expected]
    if stale:
        print("Generated OpenAPI contracts are stale:")
        for path in stale:
            print(f"- {path}")
        raise SystemExit(1)
else:
    for path, content in outputs.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content)
